#!/usr/bin/env bash
# Block hand edits to the generated Xcode project and to local signing config.
f="$(python3 -c 'import json,sys; print(json.load(sys.stdin).get("tool_input",{}).get("file_path",""))')"
case "$f" in
  *.xcodeproj/*|*/App/Info.plist) echo "Generated by XcodeGen: edit project.yml instead." >&2; exit 2 ;;
esac
exit 0
